INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('0d9b4671-dcce-4d76-901a-c0bbeee20a5a', 'Novo Fluxo', NULL, 'true', NULL, '2026-07-17T20:34:05.422585+00:00', '2026-08-27T22:07:58.035+00:00', 'exact_phrase', '["Olá! Posso ter mais informações sobre isso?", "Olá! Posso saber mais informações?", "Oi", "Olá", "Bom dia", "Boa tarde", "Boa noite", "Valor"]', E'[{"id": "message_1784317899138", "data": {"text": "🚀 Edson aqui! Obrigado por chamar.\\n\\nVou direto ao ponto porque esse é um dos grandes diferenciais da Cloud Safety:\\n\\n🔥 UMA ÚNICA CONTRATAÇÃO.\\n*+ de 130 TREINAMENTO GRAVADOS.*\\n\\nVocê paga por vida cadastrada e tem à sua disposição mais de 130 treinamentos.\\n\\nOu seja:\\n\\n1 contratação → + de 130 treinamentos.\\n\\n🎯 Treinamentos conforme NRs:\\nOnline / Híbridos (teoria online + prática presencial).\\n\\nE tudo isso dentro de uma plataforma para gestão e aplicação dos treinamentos.\\n\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 411, "height": 156}, "position": {"x": 380.4674560855187, "y": -204.65361420630242}, "selected": true}, {"id": "message_1784318661002", "data": {"text": "E não é só sobre aplicar os treinamentos, mas a gestão completa.\\n\\nVocê também pode centralizar:\\n\\n✅ Certificados\\n✅ Carteirinha com QR Code\\n✅ Vencimentos e alertas automáticos\\n✅ Gestão de ASOs\\n✅ Dashboards em tempo real\\n\\n🎯 Outros módulos: CIPA, DDS, Ginástica Laboral e Gestão de Documentos\\n\\nPara empresas, significa mais controle e menos trabalho manual.\\n\\nPara consultorias, significa mais escala e mais valor para o cliente.\\n\\n\\n💡 Mas quero te mostrar isso funcionando, porque é muito mais fácil entender vendo na prática.\\n\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 478, "height": 156}, "position": {"x": 343.2436985727339, "y": 125.89641515741639}, "selected": false}, {"id": "delay_1784318688520", "data": {"unit": "segundos", "delay": 4}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 528.0671280523652, "y": 338.3671539923066}, "selected": false}, {"id": "delay_1784318688555", "data": {"unit": "segundos", "delay": 3}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 523.328647282984, "y": -11.371326777074586}, "selected": false}, {"id": "question_1784319381540", "data": {"text": "Posso te mostrar a Cloud Safety em uma demonstração de 60 minutos?\\n\\nVocê vai conhecer a plataforma, entender o modelo por vida e ver como os + de 130 treinamentos podem funcionar na sua realidade.\\n\\nEscolha uma das opções para continuar!", "buttons": [{"id": "opt1", "url": "", "text": "👉 Quero para EMPRESA que trabalho"}, {"id": "opt2", "text": "👉 Quero para minha CONSULTORIA de SST"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 675, "height": 245}, "position": {"x": 247.22044506235522, "y": 514.570234630001}, "selected": false}, {"id": "message_1784319901400", "data": {"text": "🚀 Ótimo! Então vamos falar da sua empresa.\\n\\nCom a Cloud Safety, você centraliza em um único lugar:\\n\\n✅ + de 130 treinamentos disponíveis\\n✅ Certificados, ASOs e documentos\\n✅ Alertas de vencimentos\\n✅ Controle por colaborador\\n✅ Indicadores da gestão de SST\\n\\nMenos planilhas. Menos retrabalho. Mais controle.\\n\\nE você ainda ganha tempo para sua equipe cuidar do que realmente importa: \\na operação e a segurança das pessoas.\\n\\n📅 Quer que eu te mostre isso funcionando?\\n\\n👉 Agendar demonstração pelo link abaixo:\\n\\n👉 https://calendar.app.google/17ceegiVXiRiNf1E9\\n\\n\\n👆🏻👆🏻👆🏻👆🏻👆🏻"}, "type": "message", "dragging": false, "measured": {"width": 392, "height": 156}, "position": {"x": 1352.7862337534207, "y": 736.7285132463422}, "selected": false}, {"id": "delay_1784319921498", "data": {"unit": "segundos", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 1144.6167928786158, "y": 629.6428272114714}, "selected": false}, {"id": "delay_1784320007832", "data": {"unit": "segundos", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 1144.0362512067861, "y": 818.5592648962978}, "selected": false}, {"id": "message_1784320018266", "data": {"text": "🚀 Excelente! Então vamos falar de escala.\\n\\nCom a Cloud Safety, sua consultoria pode:\\n\\n✅ Gerenciar vários CNPJs em um único ambiente\\n✅ Disponibilizar + de 130 treinamentos aos clientes\\n✅ Automatizar certificados e vencimentos\\n✅ Centralizar treinamentos, ASOs e documentos\\n✅ Entregar mais valor sem aumentar a operação\\n\\nMais organização. Mais escala. Mais valor para o seu cliente.\\n\\nE o melhor: \\nVocê pode transformar a tecnologia em um diferencial comercial da sua consultoria.\\n\\n📅 Quer ver como funciona?\\n\\n👉 Agendar demonstração pelo link abaixo:\\n\\n👉 https://calendar.app.google/17ceegiVXiRiNf1E9\\n\\n\\n👆🏻👆🏻👆🏻👆🏻👆🏻\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 424, "height": 156}, "position": {"x": 1343.84720875709, "y": 1082.8596900832672}, "selected": false}, {"id": "delay_1784320255234", "data": {"unit": "horas", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 525.0867987626993, "y": 848.6818528151013}, "selected": false}, {"id": "message_1784320269634", "data": {"text": "Oi! Só voltando aqui rapidinho — ficou alguma dúvida ou já consigo te mostrar como funciona na prática? 🙂\\n\\n👉 Agendar demonstração pelo link abaixo:\\n\\n👉 https://calendar.app.google/17ceegiVXiRiNf1E9\\n\\n\\n👆🏻👆🏻👆🏻👆🏻👆🏻"}, "type": "message", "dragging": false, "measured": {"width": 541, "height": 156}, "position": {"x": 317.8610344900367, "y": 1027.1568929995528}, "selected": false}, {"id": "delay_1784320315347", "data": {"unit": "horas", "delay": 3}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 529.3950541148588, "y": 1243.4164445573124}, "selected": false}, {"id": "message_1784320322472", "data": {"text": "Última vez que toco no assunto por aqui: treinamento vencido ou CIPA fora do prazo pode gerar autuação em fiscalização — a Cloud Safety resolve isso automaticamente.\\nSe fizer sentido, é só me chamar. \\n\\n👉 Agendar demonstração pelo link abaixo:\\n\\n👉 https://calendar.app.google/17ceegiVXiRiNf1E9\\n\\n\\n👆🏻👆🏻👆🏻👆🏻👆🏻\\n\\nFico à disposição! 🙂"}, "type": "message", "dragging": false, "measured": {"width": 834, "height": 156}, "position": {"x": 163.96010889368347, "y": 1395.9278749886205}, "selected": false}]', '[{"id": "xy-edge__message_1784317899138-delay_1784318688555", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1784317899138", "target": "delay_1784318688555", "animated": true}, {"id": "xy-edge__delay_1784318688555-message_1784318661002", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784318688555", "target": "message_1784318661002", "animated": true}, {"id": "xy-edge__message_1784318661002-delay_1784318688520", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1784318661002", "target": "delay_1784318688520", "animated": true}, {"id": "xy-edge__delay_1784319921498-message_1784319901400", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784319921498", "target": "message_1784319901400", "animated": true}, {"id": "xy-edge__question_1784319381540opt2-delay_1784320007832", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784319381540", "target": "delay_1784320007832", "animated": true, "sourceHandle": "opt2"}, {"id": "xy-edge__delay_1784320007832-message_1784320018266", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784320007832", "target": "message_1784320018266", "animated": true}, {"id": "xy-edge__question_1784319381540next-delay_1784320255234", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784319381540", "target": "delay_1784320255234", "animated": true, "sourceHandle": "next"}, {"id": "xy-edge__delay_1784320255234-message_1784320269634", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784320255234", "target": "message_1784320269634", "animated": true}, {"id": "xy-edge__message_1784320269634-delay_1784320315347", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1784320269634", "target": "delay_1784320315347", "animated": true}, {"id": "xy-edge__delay_1784320315347-message_1784320322472", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784320315347", "target": "message_1784320322472", "animated": true}, {"id": "xy-edge__question_1784319381540opt1-delay_1784319921498", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784319381540", "target": "delay_1784319921498", "animated": true, "sourceHandle": "opt1"}, {"id": "xy-edge__delay_1784318688520-question_1784319381540", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784318688520", "target": "question_1784319381540", "animated": true}]', '227b783b-4b2e-406d-8576-d80d6967c8d7', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('1fa525bd-0d1b-4e88-b172-2d0c68de18a8', 'DIRECT MOSTRA', NULL, 'true', NULL, '2026-06-22T00:59:16.573497+00:00', '2026-07-01T20:47:54.217+00:00', 'manual', '[]', E'[{"id": "video_1782089771604", "data": {"fileName": "sem gastar com anúncios ++ -compactado.mp4", "videoUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/p5hmu237nmq_1782158476224.mp4"}, "type": "video", "dragging": false, "measured": {"width": 255, "height": 82}, "position": {"x": 227.46229099815912, "y": 76.96229099815912}, "selected": true}, {"id": "message_1782089856774", "data": {"text": "*Tudo no automático!*\\n\\nMais vendas, mais clientes sem precisar investir em tráfego pago! "}, "type": "message", "dragging": false, "measured": {"width": 450, "height": 82}, "position": {"x": 244.11143179042955, "y": 220.61143179042952}, "selected": false}]', '[{"id": "xy-edge__video_1782089771604-message_1782089856774", "type": "button", "style": {"strokeWidth": 2}, "source": "video_1782089771604", "target": "message_1782089856774", "animated": true}]', '23753033-cdf5-4d2d-9d50-9f4807c45260', NULL) ON CONFLICT DO NOTHING;
