INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('34164a34-97ac-487f-a723-cf61aabc4ce5', 'INICIO DIRETO', NULL, 'true', NULL, '2026-07-20T01:21:16.935383+00:00', '2026-08-20T18:18:00.716+00:00', 'manual', E'["Gostaria de saber sobre o sistema inovador!\\nGostaria de saber sobre o sistema inovador!"]', E'[{"id": "audio_1784510476994_oe1ld", "data": {"isPTT": true, "audioUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/hf33mo5c4qn_1787249878593.ogg", "fileName": "WhatsApp Audio 2026-08-20 at 14.46.03.ogg"}, "type": "audio", "dragging": false, "measured": {"width": 242, "height": 81}, "position": {"x": 1436.7371868023001, "y": 800.7099900111082}, "selected": true}, {"id": "question_1784510476994_9jv8d", "data": {"text": "\\n\\nAcesse o site ⤵️⭕", "buttons": [{"id": "opt1", "url": "https://maisresultadosonline.com.br/ferramentamropromo", "text": "ACESSAR AGORA"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 250, "height": 173}, "position": {"x": 885.6650314640908, "y": 936.6059262027535}, "selected": false}, {"id": "waitResponse_1784510476994_i6q1f", "data": {"timeout": 19}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 627.3275709544902, "y": 1061.895048496657}, "selected": false}, {"id": "message_1784510476994_kevis", "data": {"text": "Qual é seu instagram? compartilha aqui o link do perfil vou dar uma olhadadinha para aenteder melhor sobre o seu nicho!"}, "type": "message", "dragging": false, "measured": {"width": 598, "height": 81}, "position": {"x": 643.4685543076686, "y": 1263.623029078037}, "selected": false}, {"id": "delay_1784510476994_yq5g5", "data": {"unit": "segundos", "delay": 35}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 724.0285839907431, "y": 858.7523341180051}, "selected": false}, {"id": "crmAction_1784510476994_fn88u", "data": {"action": "Adicionar Etiqueta", "statusLabel": "FERRAMENTA MRO", "statusValue": "ferramenta-mro"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 407.8631274013592, "y": 840.3027966829276}, "selected": false}, {"id": "crmAction_1784510476994_qr8xn", "data": {"action": "Adicionar Etiqueta", "statusLabel": "Mandou instagram", "statusValue": "mandou-instagram"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 1252.0896781790511, "y": 1464.6834309772396}, "selected": false}, {"id": "waitResponse_1784510476994_1npxu", "data": {"timeout": 20}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 854.041562894464, "y": 1411.5053861675585}, "selected": false}, {"id": "message_1784510476994_2a50g", "data": {"text": "Fico no seu aguardo."}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 1001.9182857360065, "y": 1596.2475303357292}, "selected": false}, {"id": "question_1784510476994_10lwv", "data": {"text": "Para utilizar nosso sistema *você precisa ter uma maquina para instalar você tens qual desses ? Não funciona apenas em celular*\\n\\nQual você tens?", "buttons": [{"id": "opt1", "text": "Notebook/Pc"}, {"id": "opt2", "text": "Macbook"}, {"id": "btn-1784505878240", "url": "", "text": "Não tenho nenhum!"}], "anyResponse": true}, "type": "question", "dragging": false, "measured": {"width": 657, "height": 299}, "position": {"x": 738.6073395511823, "y": 11.29271445171672}, "selected": false}, {"id": "message_1784510476994_8kzez", "data": {"text": "Infelizmente, *é necessário ter um computador para instalar o nosso sistema, pois ele não funciona em celulares.* \\n\\n\\n\\nUma dica é investir em você e adquirir pelo menos um notebook básico. Esse é o mínimo necessário para trabalhar com redes sociais e também para empreender com mais eficiência."}, "type": "message", "dragging": false, "measured": {"width": 892, "height": 141}, "position": {"x": 1963.939053516645, "y": 336.20222705727616}, "selected": false}, {"id": "question_1784510476994_dji4m", "data": {"text": "*Gostaria de saber sobre a ferramenta MRO* mesmo assim?", "buttons": [{"id": "opt1", "text": "Sim"}, {"id": "opt2", "text": "Não,obrigado!"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 330, "height": 184}, "position": {"x": 1566.680187491285, "y": 1033.0276581547814}, "selected": false}]', '[{"id": "e_1784510476994_zznze", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784510476994_9jv8d", "target": "waitResponse_1784510476994_i6q1f", "animated": true, "sourceHandle": "any_response"}, {"id": "e_1784510476994_qkhja", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784510476994_yq5g5", "target": "question_1784510476994_9jv8d", "animated": true}, {"id": "e_1784510476994_94v8s", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1784510476994_i6q1f", "target": "message_1784510476994_kevis", "animated": true, "sourceHandle": "timeout"}, {"id": "e_1784510476994_7wsi8", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784510476994_9jv8d", "target": "waitResponse_1784510476994_i6q1f", "animated": true, "sourceHandle": "next"}, {"id": "e_1784510476994_c7bjz", "type": "button", "style": {"strokeWidth": 2}, "source": "audio_1784510476994_oe1ld", "target": "crmAction_1784510476994_fn88u", "animated": true}, {"id": "e_1784510476994_l678o", "type": "button", "style": {"strokeWidth": 2}, "source": "crmAction_1784510476994_fn88u", "target": "delay_1784510476994_yq5g5", "animated": true}, {"id": "e_1784510476994_b4ylg", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1784510476994_kevis", "target": "waitResponse_1784510476994_1npxu", "animated": true}, {"id