INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('62e24090-63a8-40f1-a9c0-ed7ca038f0ca', 'Novo Fluxo', NULL, 'true', NULL, '2026-08-06T16:36:54.245685+00:00', '2026-08-07T18:19:19.727+00:00', 'exact_phrase', '["Não, no momento não"]', E'[{"id": "message_1786034098188", "data": {"text": "Obrigado.\\nNão iremos mais lhe incomodar."}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 96}, "position": {"x": 460.629592791336, "y": 228.8296049983673}, "selected": false}, {"id": "crmAction_1786034163178", "data": {"action": "Adicionar Etiqueta", "statusLabel": "SAIU DA LISTA", "statusValue": "saiu-da-lista"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 536.3533529653264, "y": 346.1533712758734}, "selected": true}]', '[{"id": "xy-edge__message_1786034098188-crmAction_1786034163178", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1786034098188", "target": "crmAction_1786034163178", "animated": true}]', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611', 'saiu-da-lista') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('64bbdfa3-0c40-4f3f-bd8a-358a4f80b570', 'Novo Fluxo', NULL, 'true', NULL, '2026-06-08T16:58:30.878225+00:00', '2026-07-10T01:04:48.996+00:00', 'first_message_day', '[]', E'[{"id": "message_1780937774472", "data": {"text": "Olá me chamo Alessandra Linhares sou responsavel pelo CURSO Cabelereira Completa."}, "type": "message", "dragging": false, "measured": {"width": 442, "height": 81}, "position": {"x": -40.28955548464501, "y": -136.2200449228034}, "selected": false}, {"id": "question_1780937806882", "data": {"text": "Em que posso ajudar?", "buttons": [{"id": "opt1", "text": "Falar com alessandra"}, {"id": "opt2", "text": "CURSOS ONLINE?"}, {"id": "btn-1780937836865", "text": "Gerar Certificado"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 250, "height": 226}, "position": {"x": 168.3472668025018, "y": 77.77714048873499}, "selected": false}, {"id": "message_1780937854481", "data": {"text": "Para gerar seu certificado pode acessar direto nosso site com email de compra e gerar o certificado dentro da área de membros. \\n\\nSite\\nhttps://belezalisoperfeito.online/"}, "type": "message", "dragging": false, "measured": {"width": 639, "height": 126}, "position": {"x": -472.631668494016, "y": 574.685170288923}, "selected": true}, {"id": "message_1780942141138", "data": {"text": "Para comprar com desconto aproveite em nosso site antes que acabe. \\n\\nhttps://belezalisoperfeito.online/"}, "type": "message", "dragging": false, "measured": {"width": 362, "height": 111}, "position": {"x": 675.7712431719405, "y": 412.9547727918726}, "selected": false}, {"id": "aiAgent_1780942191530", "data": {"prompt": "Você é Alessandra linhares, voce vende um curso de cabelo completo, RESUMO COMPLETO PARA O ATENDENTE VENDER O CURSO\\n\\nO QUE É O CURSO?\\n\\nA Formação de Elite - Curso de Cabeleireira Completo é um treinamento profissional com mais de 60 aulas práticas gravadas diretamente de cursos presenciais ministrados pela especialista Alessandra Linhares.\\n\\nO aluno aprende as principais técnicas utilizadas em salão de beleza para começar a trabalhar, aumentar a renda ou se profissionalizar na área da beleza.\\n\\nPRINCIPAIS BENEFÍCIOS\\n\\n✓ Aprende uma profissão com alta demanda no mercado.\\n\\n✓ Pode começar a atender clientes e gerar renda própria.\\n\\n✓ Estuda no próprio ritmo, de onde quiser.\\n\\n✓ Acesso vitalício ao conteúdo.\\n\\n✓ Mais de 60 aulas práticas e objetivas.\\n\\n✓ Conteúdo gravado por profissional com mais de 10 anos de experiência real em salão.\\n\\n✓ Recebe certificado de conclusão.\\n\\n✓ Tem acesso a comunidade VIP.\\n\\n✓ Recebe indicação de fornecedores.\\n\\n✓ Aprende técnicas que realmente são utilizadas no dia a dia dos salões.\\n\\nO QUE O ALUNO VAI APRENDER?\\n\\n1. ALISAMENTO PROFISSIONAL\\n\\n* Progressivas\\n* Selagens\\n* Técnicas para brilho e alinhamento dos fios\\n* Aplicação correta dos produtos\\n\\n2. CORTE PROFISSIONAL\\n\\n* Técnicas modernas de corte\\n* Acabamentos profissionais\\n* Visagismo\\n* Cortes femininos mais procurados\\n\\n3. COLORIMETRIA E TONALIZAÇÃO\\n\\n* Combinação de cores\\n* Correção de tons\\n* Tonalização\\n* Evitar erros comuns em coloração\\n\\nBÔNUS INCLUSOS\\n\\n✓ Certificado de conclusão\\n✓ Comunidade VIP\\n✓ Lista de fornecedores\\n✓ Dicas de vendas e captação de clientes\\n✓ Acesso vitalício\\n\\nSOBRE A PROFESSORA\\n\\nAlessandra Linhares é fundadora do Salão de Beleza AL e possui mais de 10 anos de experiência profissional. Aprendeu a profissão através do legado familiar e hoje ensina técnicas práticas que realmente funcionam para quem deseja atuar na área da beleza.\\n\\nCOMO O ATENDENTE DEVE EXPLICAR O CURSO\\n\\n\\"Esse curso foi criado para quem deseja aprender uma profissão, começar a trabalhar na área da beleza ou aperfeiçoar suas técnicas. Você terá acesso a mais de 60 aulas práticas ensinadas por uma profissional com mais de 10 anos de experiência. Vai aprender alisamento, corte e colorimetria, além de receber certificado, acesso vitalício, comunidade exclusiva e materiais de apoio. Tudo isso por apenas R$ 47, um investimento muito abaixo do valor de cursos presenciais.\\"\\n\\nARGUMENTOS DE VENDA\\n\\n• Um único procedimento de progressiva pode pagar o valor do curso.\\n• O acesso é vitalício.\\n• O aluno pode assistir quantas vezes quiser.\\n• Conteúdo baseado em experiência real de salão.\\n• Certificado incluso.\\n• Suporte e comunidade para auxiliar na jornada.\\n• Valor promocional de apenas R$ 47.\\n\\nPERGUNTA DE FECHAMENTO\\n\\n\\"Você quer aprender uma profissão que pode gerar renda e ter acesso vitalício a mais de 60 aulas completas por apenas R$ 47? Posso te ajudar a garantir sua vaga agora.\\"\\n\\n\\nO curso tem garantia de 7 dias.\\n\\nsempre vai mandar o site para direcionar a comprar pelo site.   https://belezalisoperfeito.online/", "initialMessage": "Olá sobre qual seria seu assunto ?", "labelOnHumanTransfer": "Atenção: Humano Necessário", "wait_response_before_start": true}, "type": "aiAgent", "dragging": false, "measured": {"width": 1652, "height": 292}, "position": {"x": 658.4812223393213, "y": -289.6532637306505}, "selected": false}, {"id": "message_1781139063819", "data": {"text": "precisa de mais alguma ajuda..."}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 192.45083281097965, "y": 923.7188677705378}, "selected": false}, {"id": "question_1782129503542", "data": {"text": "Precisa de mais alguma ajuda?", "buttons": [{"id": "opt1", "text": "Sim"}, {"id": "opt2", "text": "Não!"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 250, "height": 185}, "position": {"x": 130.00529945915656, "y": 1100.7800115681662}, "selected": false}, {"id": "message_1782129507334", "data": {"text": "Certo, qualquer situação é só chamar."}, "type": "message", "dragging": false, "measured": {"width": 206, "height": 81}, "position": {"x": 667.5906867544948, "y": 1106.3653988635042}, "selected": false}]', '[{"id": "xy-edge__message_1780937774472-question_1780937806882", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1780937774472", "target": "question_1780937806882", "animated": true}, {"id": "xy-edge__question_1780937806882btn-1780937836865-message_1780937854481", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1780937806882", "target": "message_1780937854481", "animated": true, "sourceHandle": "btn-1780937836865"}, {"id": "xy-edge__question_1780937806882opt2-message_1780942141138", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1780937806882", "target": "message_1780942141138", "animated": true, "sourceHandle": "opt2"}, {"id": "xy-edge__question_1780937806882opt1-aiAgent_1780942191530", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1780937806882", "target": "aiAgent_1780942191530", "animated": true, "sourceHandle": "opt1"}, {"id": "xy-edge__message_1780937854481-message_1781139063819", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1780937854481", "target": "message_1781139063819", "animated": true}, {"id": "xy-edge__message_1780942141138-message_1781139063819", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1780942141138", "target": "message_1781139063819", "animated": true}, {"id": "xy-edge__message_1781139063819-question_1782129503542", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1781139063819", "target": "question_1782129503542", "animated": true}, {"id": "xy-edge__question_1782129503542opt2-message_1782129507334", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1782129503542", "target": "message_1782129507334", "animated": true, "sourceHandle": "opt2"}, {"id": "xy-edge__question_1782129503542opt1-question_178093780