INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('878fb810-0b36-48a5-b17d-8473cf5caa57', 'Novo Fluxo (Cópia)', NULL, 'true', NULL, '2026-08-17T11:55:41.775765+00:00', '2026-08-17T19:13:41.31+00:00', 'exact_phrase', '["Olá! Posso ter mais informações sobre a Radio Para Loja?"]', E'[{"id": "message_1786967742120_40d50", "data": {"text": "Olá, aqui é Frank Eler.\\nDesde já, obrigado pelo seu contato!"}, "type": "message", "dragging": false, "measured": {"width": 209, "height": 96}, "position": {"x": 425.1659526203682, "y": 182.86596482739952}, "selected": false}, {"id": "message_1786967742120_s3mxr", "data": {"text": "A gente cria todas as chamadas de acordo com sua estratégia, seja para ficar na porta (chamando atenção de quem passa na rua), ou se preferir para dentro da loja (agradecendo pela preferencia, anunciando ofertas, etc..)\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 1135, "height": 96}, "position": {"x": 156.83596184820294, "y": 869.3198766171195}, "selected": false}, {"id": "message_1786967742120_o3veb", "data": {"text": "Certo!\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 96}, "position": {"x": 2085.3674768673, "y": 852.7091028454684}, "selected": false}, {"id": "waitResponse_1786967742120_jtofc", "data": {"timeout": 20}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 1005.4654765554799, "y": 1201.4123023472296}, "selected": false}, {"id": "message_1786967742120_bj8z7", "data": {"text": "Olá, ainda estamos aqui a disposição para esclarecer suas dúvidas."}, "type": "message", "dragging": false, "measured": {"width": 359, "height": 81}, "position": {"x": 1436.4655294412298, "y": 1361.3528668803501}, "selected": false}, {"id": "message_1786967742120_olsba", "data": {"text": "Vou te explicar como funciona a Radio Para Sua Loja: \\n\\n✅​ Nós criamos a rádio, com toda produção inclusa, vinhetas, ofertas, hora certa, etc...\\n\\nO valor é R$99,97 mensal com todas a atualizações inclusas.\\n\\nFica pronta em até 1 hora após contratação.\\n\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 458, "height": 156}, "position": {"x": 329.5059030018358, "y": 412.72008291406183}, "selected": false}, {"id": "delay_1786967742120_ztsfg", "data": {"unit": "segundos", "delay": 7}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 529.2160853328941, "y": 662.1602879847871}, "selected": false}, {"id": "delay_1786967742120_q8vn0", "data": {"unit": "segundos", "delay": 5}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 520.543202585892, "y": 1050.678623316979}, "selected": false}, {"id": "message_1786967742120_fm6ox", "data": {"text": "Qual das duas te atende melhor? "}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 526.5136239551889, "y": 1205.3690441497179}, "selected": false}, {"id": "delay_1786967922686", "data": {"unit": "segundos", "delay": 5}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 369.46588459093243, "y": -26.626394498881723}, "selected": false}, {"id": "crmAction_1786988835255", "data": {"action": "Adicionar Etiqueta", "statusLabel": "RADIO LOJA", "statusValue": "radio-loja"}, "type": "crmAction", "measured": {"width": 180, "height": 105}, "position": {"x": 1136.9308718502461, "y": 674.0924130972913}, "selected": true}]', '[{"id": "e_1786967742120_g10cf", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1786967742120_jtofc", "target": "message_1786967742120_o3veb", "animated": true, "sourceHandle": "responded"}, {"id": "e_1786967742120_anga8", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1786967742120_jtofc", "target": "message_1786967742120_bj8z7", "animated": true, "sourceHandle": "timeout"}, {"id": "e_1786967742120_qzxlo", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1786967742120_40d50", "target": "message_1786967742120_olsba", "animated": true}, {"id": "e_1786967742120_g05ug", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1786967742120_ztsfg", "target": "message_1786967742120_s3mxr", "animated": true}, {"id": "e_1786967742120_lhype", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1786967742120_s3mxr", "target": "delay_1786967742120_q8vn0", "animated": true}, {"id": "e_1786967742120_h16n6", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1786967742120_q8vn0", "target": "message_1786967742120_fm6ox", "animated": true}, {"id": "e_1786967742120_fvdyq", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1786967742120_fm6ox", "target": "waitResponse_1786967742120_jtofc", "animated": true}, {"id": "xy-edge__delay_1786967922686-message_1786967742120_40d50", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1786967922686", "target": "message_1786967742120_40d50", "animated": true}, {"id": "xy-edge__message_1786967742120_olsba-crmAction_1786988835255", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1786967742120_olsba", "target": "crmAction_1786988835255", "animated": true}, {"id": "xy-edge__crmAction_1786988835255-delay_1786967742120_ztsfg", "type": "button", "style": {"strokeWidth": 2}, "source": "crmAction_1786988835255", "target": "delay_1786967742120_ztsfg", "animated": true}]', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611', 'radio-loja') ON CONFLICT DO NOTHING;
