INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('a0bb6b73-a6e2-458d-a08b-353366669bb6', 'valortrafegocurso', NULL, 'true', NULL, '2026-08-18T17:27:51.518203+00:00', '2026-08-18T17:27:51.314+00:00', 'manual', '[]', E'[{"id": "image_1787073954322", "data": {"fileName": "TRAFEEE.png", "imageUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/x40s6c8g3jq_1787074016869.png"}, "type": "image", "dragging": false, "measured": {"width": 158, "height": 127}, "position": {"x": 480.5614311849496, "y": 324.2264937111271}, "selected": false}, {"id": "audio_1787073957522", "data": {"isPTT": true, "audioUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/yq9hg07by8_1787073966871.ogg", "fileName": "TRAFEGPAGOEXPLICA.ogg"}, "type": "audio", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 443.0283049274047, "y": 111.41894518619375}, "selected": false}, {"id": "message_1787074023377", "data": {"text": "*CURSO DE TRÁFEGO PAGO PARA O SEU NEGÓCIO!* 🚀\\n\\nVamos criar *as campanhas junto com você, em uma ligação*, de acordo com o seu negócio e seus objetivos.\\n\\nDurante o curso, vamos *criar seus anúncios, definir as estratégias e colocar tudo em prática*, para que você entenda de verdade como funciona o tráfego pago.\\n\\nA ideia é que você *aprenda a criar e gerenciar suas próprias campanhas* e consiga dar continuidade sozinho após o curso, sem depender de outra pessoa para fazer seu tráfego.\\n\\nAlém da aula, você terá:\\n\\n*✅ Suporte durante 1 semana*\\nPara tirar dúvidas, receber assistência e ter ajuda caso precise durante a aplicação das estratégias.\\n\\n*🎥 Aula gravada*\\nNossa aula será gravada e disponibilizada para você, para que possa *reassistir quando quiser* e consultar o conteúdo sempre que precisar.\\n\\n*🔥 APENAS 10 VAGAS*\\n\\n*💰 R$997*\\n\\n*Em até 10x de R$97 sem juros*\\n\\nUma oportunidade para você *aprender tráfego pago na prática, criar suas próprias campanhas e assumir o controle dos seus anúncios.*"}, "type": "message", "dragging": false, "measured": {"width": 876, "height": 156}, "position": {"x": 402.1001044034889, "y": 584.2194776913149}, "selected": false}, {"id": "delay_1787074051753", "data": {"unit": "segundos", "delay": 50}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 650.398588083654, "y": 205.76573098967344}, "selected": true}]', '[{"id": "xy-edge__image_1787073954322-message_1787074023377", "type": "button", "style": {"strokeWidth": 2}, "source": "image_1787073954322", "target": "message_1787074023377", "animated": true}, {"id": "xy-edge__audio_1787073957522-delay_1787074051753", "type": "button", "style": {"strokeWidth": 2}, "source": "audio_1787073957522", "target": "delay_1787074051753", "animated": true}, {"id": "xy-edge__delay_1787074051753-image_1787073954322", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1787074051753", "target": "image_1787073954322", "animated": true}]', '23753033-cdf5-4d2d-9d50-9f4807c45260', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('a25be1c2-4713-4b3e-a6f2-0edea59ddbc7', 'ATENDIMENTO INICIAL', NULL, 'false', NULL, '2026-07-19T22:32:46.339588+00:00', '2026-08-22T19:14:11.391+00:00', 'manual', E'["Gostaria de saber sobre o sistema inovador!\\nGostaria de saber sobre o sistema inovador!"]', E'[{"id": "message_1784500366491_pt0hl", "data": {"text": "Olá me chamo *Gabriel*, sou responsavel pelo *sistema inovador* ! "}, "type": "message", "dragging": false, "measured": {"width": 348, "height": 81}, "position": {"x": 181.933556988151, "y": 100.77876390582179}, "selected": false}, {"id": "question_1784500366491_09t59", "data": {"text": "Você *tem empresa*? vende *algum produto ou presta algum serviço?*", "buttons": [{"id": "opt1", "text": "Sim"}, {"id": "opt2", "text": "Não"}], "anyResponse": true}, "type": "question", "dragging": false, "measured": {"width": 383, "height": 228}, "position": {"x": -30.09012202270759, "y": 271.9393578832376}, "selected": false}, {"id": "audio_1784500366491_bnkh1", "data": {"isPTT": true, "audioUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/x4skbj2hd1a_1787249620916.ogg", "fileName": "WhatsApp Audio 2026-08-20 at 14.46.03.ogg"}, "type": "audio", "dragging": false, "measured": {"width": 242, "height": 81}, "position": {"x": 1436.7371868023001, "y": 800.7099900111082}, "selected": false}, {"id": "question_1784500366491_ec3fn", "data": {"text": "\\n\\nAcesse o site ⤵️⭕", "buttons": [{"id": "opt1", "url": "https://maisresultadosonline.com.br/ferramentamropromo", "text": "ACESSAR AGORA"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 250, "height": 173}, "position": {"x": 885.6650314640908, "y": 936.6059262027535}, "selected": false}, {"id": "waitResponse_1784500366491_qf7nm", "data": {"timeout": 19}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 627.3275709544902, "y": 1061.895048496657}, "selected": false}, {"id": "message_1784500366491_hx4qm", "data": {"text": "Qual é seu instagram? compartilha aqui o link do perfil vou dar uma olhadadinha para aenteder melhor sobre o seu nicho!"}, "type": "message", "dragging": false, "measured": {"width": 598, "height": 81}, "position": {"x": 643.4685543076686, "y": 1263.623029078037}, "selected": false}, {"id": "delay_1784500366491_riqix", "data": {"unit": "segundos", "delay": 38}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 724.0285839907431, "y": 858.7523341180051}, "selected": true}, {"id": "crmAction_1784500366491_llwla", "data": {"action": "Adicionar Etiqueta", "statusLabel": "FERRAMENTA MRO", "statusValue": "ferramenta-mro"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 407.8631274013592, "y": 840.3027966829276}, "selected": false}, {"id": "crmAction_1784500366491_1xqhn", "data": {"action": "Adicionar Etiqueta", "statusLabel": "Mandou instagram", "statusValue": "mandou-instagram"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 1197.5896781790511, "y": 1419.6834309772396}, "selected": false}, {"id": "waitResponse_1784500366491_kmmgm", "data": {"timeout": 20}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 854.041562894464, "y": 1411.5053861675585}, "selected": false}, {"id": "message_1784500366491_qegil", "data": {"text": "Fico no seu aguardo."}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 994.4182857360065, "y": 1649.2475303357292}, "selected": false}, {"id": "question_1784500414627", "data": {"text": "Você precisa vender mais? mais engajamento ? clientes ? seguidores? ", "buttons": [{"id": "opt1", "text": "Sim "}, {"id": "opt2", "text": "não"}], "anyResponse": true}, "type": "question", "dragging": false, "measured": {"width": 378, "height": 228}, "position": {"x": 567.7383395939563, "y": -151.13649303648333}, "selected": false}, {"id": "question_1784500524923", "data": {"text": "Você gostaria de fazer isso hoje ainda? qual sua prioridade?", "buttons": [{"id": "opt1", "text": "Sim, hoje!"}, {"id": "opt2", "text": "Só estou pesquisando"}], "anyResponse": true}, "type": "question", "dragging": false, "measured": {"width": 327, "height": 228}, "position": {"x": 1764.39069117469, "y": 159.28635924568007}, "selected": false}, {"id": "delay_1784500629468", "data": {"unit": "segundos", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 1984.2242457092398, "y": 437.53729403713044}, "selected": false}, {"id": "question_1784505839944", "data": {"text": "Para utilizar nosso sistema *você precisa ter uma maquina para instalar você tens qual desses ? Não funciona apenas em celular*\\n\\nQual você tens?", "buttons": [{"id": "opt1", "text": "Notebook/Pc"}, {"id": "opt2", "text": "Macbook"}, {"id": "btn-1784505878240", "url": "", "text": "Não tenho nenhum!"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 657, "height": 254}, "position": {"x": 959.3967797852451, "y": 502.8693225038012}, "selected": false}, {"id": "message_1784505910632", "data": {"text": "Infelizmente, *é necessário ter um computador para instalar o nosso sistema, pois ele não funciona em celulares.* \\n\\n\\n\\nUma dica é investir em você e adquirir pelo menos um notebook básico. Esse é o mínimo necessário para trabalhar com redes sociais e também para empreender com mais eficiência."}, "type": "message", "dragging": false, "measured": {"width": 892, "height": 141}, "position": {"x": 1751.4298578421935, "y": 765.8154118261673}, "selected": false}, {"id": "question_1784505930256", "data": {"text": "*Gostaria de saber sobre a ferramenta MRO* mesmo assim?", "buttons": [{"id": "opt1", "text": "Sim"}, {"id": "opt2", "text": "Não,obrigado!"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 330, "height": 184}, "position": {"x": 1566.680187491285, "y": 1033.0276581547814}, "selected": false}, {"id": "message_1784510404954", "data": {"text": "Certo, me explica aqui o que você precisa? em que podemos ajudar?"}, "type": "message", "dragging": false, "measured": {"width": 351, "height": 81}, "position": {"x": 1331.4759130201214, "y": -111.62976072793786}, "selected": false}, {"id": "delay_1784549541778", "data": {"unit": "segundos", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 574.3172617915213, "y": 261.46693892696436}, "selected": false}, {"id": "delay_1784549561714", "data": {"unit": "segundos", "delay": 2}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 1288.5533349983505, "y": 250.53439290812187}, "selected": false}, {"id": "message_1784554408190", "data": {"text": "Chegou a ver nossa proposta em nosso site? "}, "type": "message", "dragging": false, "measured": {"width": 241, "height": 81}, "position": {"x": 1454.8834866325105, "y": 1468.1678625978075}, "selected": false}]', '[{"id": "e_1784500366491_x8u18", "type": "button", "style": {"strokeWidth": 2}, "source": "message_1784500366491_pt0hl", "target": "question_1784500366491_09t59", "animated": true}, {"id": "e_1784500366491_u0fkb", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1784500366491_ec3fn", "target": "waitResponse_1784500366491_qf7nm", "animated": true, "sourceHandle": "any_response"}, {"id": "e_1784500366491_yn0hw", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1784500366491_riqix", "target": "question_1784500366491_ec3fn", "animated": true}, {"id": "e_1784500366491_0l3cl", "type": "button", "style": {"strokeWidth": 2}, "source": "wait