INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('a6f3359c-b7be-419a-a5e0-00d6e16e7cdc', 'GRUPPO WJST', NULL, 'true', NULL, '2026-07-05T16:35:04.3155+00:00', '2026-07-06T00:33:28.25+00:00', 'manual', '[]', E'[{"id": "question_1783297322773", "data": {"text": "*PARTICIPE DO NOSSO GRUPO NO WHATSAPP* !\\n\\nEste espaço é para compartilhar resultados, dicas, estratégias e aprendizados que possam ajudar toda a comunidade.\\n\\n💬 *Caso tenha alguma dúvida mais específica sobre o seu projeto ou precise de um atendimento individual, nossa equipe está disponível pelo WhatsApp*\\n\\n\\n🚫 *Pedimos apenas que*:\\n\\n- Não divulguem links.\\n- Não façam propaganda ou divulgação de produtos e serviços externos.\\n- Mantenham as conversas voltadas para MRO, marketing e crescimento dos negócios.\\n\\n- *Contamos com a colaboração de todos para manter este grupo organizado, útil e produtivo*.", "buttons": [{"id": "opt_1783297322773", "url": "https://chat.whatsapp.com/HQIRZucVCpo1504xK7OZhL", "text": "CLIQUE E PARTICIPE"}], "fileName": "participe...png", "imageUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/hoc462dq72_1783297334714.png", "videoUrl": "", "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 568, "height": 219}, "position": {"x": 167.66527651179348, "y": 173.40192444882325}, "selected": true}]', '[]', '23753033-cdf5-4d2d-9d50-9f4807c45260', NULL) ON CONFLICT DO NOTHING;
