INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('ad536178-d1cf-4983-a217-0fc48dbd8330', 'Novo Fluxo', NULL, 'true', NULL, '2026-08-05T11:54:19.20641+00:00', '2026-08-05T11:54:18.908+00:00', 'exact_phrase', '["Confirmo Recebimento"]', E'[{"id": "message_1785930563800", "data": {"text": "Excelente!\\n\\nNossa especialidade é: \\n\\n✅ Criação de Radio da Sua Loja com todas gravações inclusas.\\n\\n✅ Gravação de Propaganda Para Porta de Loja com 5 horas de música e fala do locutor de música em musica.\\n\\n✅ Gravação de Propaganda Para Carro de Som.\\n\\nQuando precisar, é só chamar!\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 575, "height": 156}, "position": {"x": 360.868435991306, "y": 197.66842378427475}, "selected": true}]', '[]', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('ba5a0ed2-8a40-4b28-a17f-60f4c3fb1834', 'CURSO DE TRAFEGO PAG1', NULL, 'true', NULL, '2026-08-18T00:05:13.425853+00:00', '2026-08-18T00:08:09.154+00:00', 'exact_phrase', '["Gostaria de saber sobre o curso de trafego pago !"]', '[{"id": "message_1787010995581", "data": {"text": "Olá me chamo *Gabriel* sou responsavel pela agência de marketing *MRO - Mais Resultados Online*"}, "type": "message", "dragging": false, "measured": {"width": 507, "height": 81}, "position": {"x": 403.71703070015997, "y": -142.27828762339158}, "selected": false}, {"id": "question_1787011036581", "data": {"text": "Você tens noção em TRAFEGO PAGO? já anunciou alguma vez?", "buttons": [{"id": "opt1", "text": "Sim"}, {"id": "opt2", "text": "não"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 344, "height": 184}, "position": {"x": 480.3436989570579, "y": 507.0057679714075}, "selected": false}, {"id": "message_1787011077932", "data": {"text": "Certo, hoje você tens empresa? vende algum produto? "}, "type": "message", "dragging": false, "measured": {"width": 287, "height": 81}, "position": {"x": 1078.9964739730376, "y": 608.4003215405036}, "selected": false}, {"id": "message_1787011111780", "data": {"text": "Qual seu objetivo com nosso curso de trafego pago? *pode me enviar um audio se quiser*. "}, "type": "message", "dragging": false, "measured": {"width": 458, "height": 81}, "position": {"x": 1104.8165310191284, "y": 770.0598538755364}, "selected": false}, {"id": "question_1787011166292", "data": {"text": "Qual seu nivel de conhecimento hoje em *trafego pago*? ", "buttons": [{"id": "opt1", "text": "BAIXO"}, {"id": "opt2", "text": "MÉDIO"}, {"id": "btn-1787011231996", "url": "", "text": "ALTO"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 316, "height": 224}, "position": {"x": 1034.9589204294623, "y": 264.514809544358}, "selected": false}, {"id": "message_1787011280836", "data": {"text": "Qual seu objetivo com nosso curso de trafego pago? *pode me enviar um audio se quiser*. "}, "type": "message", "dragging": false, "measured": {"width": 458, "height": 81}, "position": {"x": 1805.7113730888352, "y": 443.2925030133902}, "selected": false}, {"id": "message_1787011327268", "data": {"text": "Antes de explicar sobre nosso curso *preciso conhecer um pouco sobre você*..."}, "type": "message", "dragging": false, "measured": {"width": 406, "height": 81}, "position": {"x": 441.7010053235226, "y": 369.2383952220153}, "selected": false}, {"id": "waitResponse_1787011416515", "data": {"timeout": 20}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 1419.1490940489387, "y": 328.1268657338236}, "selected": false}, {"id": "message_1787011453699", "data": {"text": "Fico no seu aguardo"}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 1604.1434745595009, "y": 519.1212460791266}, "selected": false}, {"id": "delay_1787011564955", "data": {"unit": "segundos", "delay": 1}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 605.240879766696, "y": 186.1386676371547}, "selected": false}, {"id": "crmAction_1787011669018", "data": {"action": "Adicionar Etiqueta", "statusLabel": "CURSO TRAFEGO", "statusValue": "curso-trafego"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 576.9530920490647, "y": -9.117641697965723}, "selected": true}]', '[{"id": "xy-edge__question_1787011036581opt2-message_1787011077932", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1787011036581", "target": "message_1787011077932", "animated": true, "sourceHandle": "opt2"}, {"id": "xy-edge__message_1787011077932-message_1787011111780", "t