INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('bc3df550-4513-4783-b631-ef87f77c37cc', 'audioinici', NULL, 'true', NULL, '2026-07-04T12:53:47.98157+00:00', '2026-08-20T18:14:43.371+00:00', 'exact_phrase', '["Vim pelo site, gostaria de saber mais !"]', E'[{"id": "audio_1783169628554_8f76l", "data": {"isPTT": true, "audioUrl": "https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/flow-media/yorwnoi7ym8_1787249680458.ogg", "fileName": "WhatsApp Audio 2026-08-20 at 14.46.03.ogg"}, "type": "audio", "dragging": false, "measured": {"width": 242, "height": 81}, "position": {"x": 777.4576663697793, "y": 428.3705762338085}, "selected": true}, {"id": "question_1783169628554_7ljbg", "data": {"text": "\\n\\nAcesse o site ⤵️⭕", "buttons": [{"id": "opt1", "url": "https://maisresultadosonline.com.br/ferramentamropromo", "text": "ACESSAR AGORA"}], "anyResponse": false}, "type": "question", "dragging": false, "measured": {"width": 250, "height": 173}, "position": {"x": 957.9660772845239, "y": 769.7498392741338}, "selected": false}, {"id": "waitResponse_1783169628554_r3y2b", "data": {"timeout": 60}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 573.8051745435616, "y": 979.0627683368866}, "selected": false}, {"id": "message_1783169628554_jgm8p", "data": {"text": "Qual é seu instagram? compartilha aqui o link do perfil vou dar uma olhadadinha para aenteder melhor sobre o seu nicho!"}, "type": "message", "dragging": false, "measured": {"width": 598, "height": 81}, "position": {"x": 643.4685543076686, "y": 1263.623029078037}, "selected": false}, {"id": "delay_1783169628554_tjq2u", "data": {"unit": "segundos", "delay": 15}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 780.7633823656681, "y": 669.9386852154609}, "selected": false}, {"id": "crmAction_1783169628554_wbrnd", "data": {"action": "Adicionar Etiqueta", "statusLabel": "FERRAMENTA MRO", "statusValue": "ferramenta-mro"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 1000.4445405660167, "y": 518.543231744875}, "selected": false}]', '[{"id": "e_1783169628554_nyo1u", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1783169628554_7ljbg", "target": "waitResponse_1783169628554_r3y2b", "animated": true, "sourceHandle": "any_response"}, {"id": "e_1783169628554_cj4pz", "type": "button", "style": {"strokeWidth": 2}, "source": "delay_1783169628554_tjq2u", "target": "question_1783169628554_7ljbg", "animated": true}, {"id": "e_1783169628554_4rrwz", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1783169628554_r3y2b", "target": "message_1783169628554_jgm8p", "animated": true, "sourceHandle": "timeout"}, {"id": "e_1783169628554_opcg5", "type": "button", "style": {"strokeWidth": 2}, "source": "question_1783169628554_7ljbg", "target": "waitResponse_1783169628554_r3y2b", "animated": true, "sourceHandle": "next"}, {"id": "e_1783169628554_det33", "type": "button", "style": {"strokeWidth": 2}, "source": "audio_1783169628554_8f76l", "target": "crmAction_1783169628554_wbrnd", "animated": true}, {"id": "e_1783169628554_m19e3", "type": "button", "style": {"strokeWidth": 2}, "source": "crmAction_1783169628554_wbrnd", "target": "delay_1783169628554_tjq2u", "animated": true}]', '23753033-cdf5-4d2d-9d50-9f4807c45260', NULL) ON CONFLICT DO NOTHING;
INSERT INTO public.crm_flows (id, name, description, is_active, trigger_keyword, created_at, updated_at, trigger_type, trigger_keywords, nodes, edges, user_id, trigger_tag) VALUES ('bd8b9527-121d-497f-a0e8-608ff49ec90c', 'Novo Fluxo', NULL, 'true', NULL, '2026-08-03T16:18:21.24325+00:00', '2026-08-17T19:13:15.604+00:00', 'exact_phrase', '["Olá! Posso ter mais informações sobre a Gravação Para Porta de Loja?"]', E'[{"id": "message_1785773067319", "data": {"text": "Olá, aqui é Frank Eler.\\nDesde já, obrigado pelo seu contato!"}, "type": "message", "dragging": false, "measured": {"width": 209, "height": 96}, "position": {"x": 425.1659526203682, "y": 182.86596482739952}, "selected": false}, {"id": "message_1785773439346", "data": {"text": "A gente grava para ficar na porta (chamando atenção de quem passa na rua), ou se preferir para dentro da loja (agradecendo pela preferencia, anunciando ofertas, etc..)\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 870, "height": 96}, "position": {"x": 156.83596184820294, "y": 869.3198766171195}, "selected": false}, {"id": "message_1785773713135", "data": {"text": "Certo!\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 96}, "position": {"x": 2085.3674768673, "y": 852.7091028454684}, "selected": false}, {"id": "waitResponse_1785774178778", "data": {"timeout": 20}, "type": "waitResponse", "dragging": false, "measured": {"width": 220, "height": 139}, "position": {"x": 1005.4654765554799, "y": 1201.4123023472296}, "selected": false}, {"id": "message_1785774512070", "data": {"text": "Olá, ainda estamos aqui a disposição para esclarecer suas dúvidas."}, "type": "message", "dragging": false, "measured": {"width": 359, "height": 81}, "position": {"x": 1436.4655294412298, "y": 1361.3528668803501}, "selected": false}, {"id": "message_1786406631284", "data": {"text": "Vou te explicar como funciona a Gravação de Propaganda para Porta de Loja: \\n\\n✅​ Nós gravamos Propaganda Porta de loja com 5 horas de musica, e fala do locutor de musica em musica.\\n\\nO valor é R$100, e fica pronto em aproximadamente 1 hora após confirmação do pedido.\\n\\nFicando pronto a gente envia um link do Google Drive para baixar.\\n\\n\\n"}, "type": "message", "dragging": false, "measured": {"width": 559, "height": 156}, "position": {"x": 329.5059030018358, "y": 412.72008291406183}, "selected": false}, {"id": "delay_1786965856350", "data": {"unit": "segundos", "delay": 7}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 529.2160853328941, "y": 662.1602879847871}, "selected": false}, {"id": "delay_1786966079227", "data": {"unit": "segundos", "delay": 5}, "type": "delay", "dragging": false, "measured": {"width": 150, "height": 81}, "position": {"x": 520.543202585892, "y": 1050.678623316979}, "selected": false}, {"id": "message_1786966167209", "data": {"text": "Qual das duas te atende melhor? "}, "type": "message", "dragging": false, "measured": {"width": 200, "height": 81}, "position": {"x": 526.5136239551889, "y": 1205.3690441497179}, "selected": false}, {"id": "crmAction_1786989357677", "data": {"action": "Adicionar Etiqueta", "statusLabel": "PORTA DE LOJA", "statusValue": "porta-de-loja"}, "type": "crmAction", "dragging": false, "measured": {"width": 180, "height": 105}, "position": {"x": 897.2864504775218, "y": 235.69417138770768}, "selected": true}]', '[{"id": "xy-edge__waitResponse_1785774178778responded-message_1785773713135", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1785774178778", "target": "message_1785773713135", "animated": true, "sourceHandle": "responded"}, {"id": "xy-edge__waitResponse_1785774178778timeout-message_1785774512070", "type": "button", "style": {"strokeWidth": 2}, "source": "waitResponse_1785774178778", "target": "message_1785774512070", "animated": true, "sourceHandle": "timeout"}, {"id": "xy-edge__message_1786406631284-delay_1786965856350", "type": "button", "style": {