INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1016512504712306', 'abordagem_sorveterias', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Sua sorveteria merece um ambiente tão gostoso quanto o sorvete 🍦🎵\\n\\nA música certa muda tudo: deixa o cliente mais à vontade, aumenta o tempo que ele fica na loja e reforça a identidade da sua marca, e claro, melhora o faturamento!\\n\\nCriamos uma rádio indoor 100% personalizada para o seu negócio, com playlist pensada pro seu público.\\n\\nChama a gente agora e receba uma amostra grátis pra ver (e ouvir) a diferença.", "type": "BODY"}]', '2026-08-09T17:45:30.587176+00:00', '2026-08-18T19:31:26.69+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
