INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1069287878872492', 'confirmacao_cadastro', 'UTILITY', 'pt_BR', 'APPROVED', E'[{"text": "Olá {{1}} tudo bem? \\nVerificamos que o seu contato está adicionado à nossa lista de atualizações. \\nPara garantir a segurança dos seus dados e manter o seu cadastro ativo no nosso sistema de atendimento, por favor, clique no botão abaixo para confirmar o recebimento desta mensagem.", "type": "BODY", "example": {"body_text": [["Exemplo"]]}}, {"type": "BUTTONS", "buttons": [{"text": "Confirmo Recebimento", "type": "QUICK_REPLY"}]}]', '2026-08-05T11:18:44.573617+00:00', '2026-08-18T19:31:27.545+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1087662397154092', '30selecao', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"type": "HEADER", "format": "VIDEO", "example": {"header_handle": ["https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/templates/30selecao_header_1787101184014.mp4"]}}, {"text": "🎉 *VOCÊ GANHOU!*\\n\\nParabéns! 🎁 Você foi *um dos 30 sorteados* da Academia Conexão Fit!\\n\\nComo presente, você recebeu uma oportunidade *exclusiva* para iniciar sua transformação com:\\n\\n💪 *Avaliação física*\\n🏋️ *Prescrição do treinamento*\\n💊 *Prescrição de suplementos*\\n🧪 *Prescrição de manipulados*\\n\\nTudo com a orientação do *Professor Neto, treinador de atletas*, para você começar seu *antes e depois* com acompanhamento profissional.\\n\\n⚠️ *Essa oportunidade é exclusiva para os 30 sorteados* e não será divulgada no Facebook ou Instagram.\\n\\n👉 *Você ganhou essa oportunidade. Agora só precisa aproveitar!*\\n\\nClique no botão abaixo e fale com nossa equipe:", "type": "BODY"}, {"type": "BUTTONS", "buttons": [{"text": "QUERO APROVEITAR", "type": "QUICK_REPLY"}]}]', '2026-08-18T23:29:28.114883+00:00', '2026-08-19T00:59:46.022+00:00', NULL, 'false', NULL, 'false', 'e1e740ce-4033-449c-80c3-94d555ddd882') ON CONFLICT DO NOTHING;
