INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1363827618533810', 'abordagem_academia', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Olá! 👋\\n\\nSei que deve estar corrido ai na  academia agora,  mas queria te fazer uma pergunta rápida.\\n\\nHoje vocês já têm uma rádio personalizada na academia ou apenas deixam uma playlist tocando?\\n\\nNós criamos uma Rádio Indoor exclusiva para academias, com músicas, vinhetas personalizadas e anúncios dos próprios serviços, como planos, avaliação física, personal trainer, suplementos e promoções.\\n\\nO ambiente fica muito mais profissional e vocês ainda aproveitam o próprio som da academia para divulgar o que realmente gera faturamento.\\n\\nSe fizer sentido para você, posso mostrar em menos de 2 minutos como funciona.", "type": "BODY"}, {"type": "BUTTONS", "buttons": [{"text": "Sim, tenho interesse", "type": "QUICK_REPLY"}, {"text": "Não, no momento não", "type": "QUICK_REPLY"}]}]', '2026-08-04T23:08:33.520216+00:00', '2026-08-18T19:31:27.976+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
