INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1372235508398130', 'tabela_imo_s_a', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"type": "HEADER", "format": "IMAGE", "example": {"header_handle": ["https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/templates/tabela_imo_s_a_header_1787948399624.jpg"]}}, {"text": "🚨 CONDIÇÃO ESPECIAL LIBERADA!\\n\\nReduzimos a taxa, retiramos a adesão e agora você pode começar seu projeto pagando uma parcela 50% menor até a contemplação.\\n\\nCrédito de R$ 120 mil a R$ 600 mil para:\\n🏠 Compra de imóvel\\n🏗️ Construção\\n💰 Capital de giro\\n🔑 Quitação de financiamento\\n\\nUma forma de avançar no seu projeto preservando seu caixa.\\n\\nQual dessas finalidades você precisa hoje? Me fala também o valor aproximado e eu faço uma simulação pra você.", "type": "BODY"}]', '2026-08-28T15:19:54.441343+00:00', '2026-08-28T20:20:01.696+00:00', NULL, 'false', NULL, 'false', 'e9c6a4d0-fa09-45f8-bf84-4962799e565a') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('1402091561847998', 'abordagem_geral', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Como vai as vendas por ai?\\n\\nTemos duas opções para te ajudar a vender mais: \\n\\n✅​ *1ª Opção:* Rádio Exclusiva da Sua Loja com todas gravações e atualizações inclusas.\\n\\n✅​ *2ª Opção:* Propaganda Porta de loja com 5 horas de musica, e fala do locutor de musica em musica.\\n\\nSe algum dia precisar, é só chamar...", "type": "BODY"}]', '2026-08-15T13:58:27.596413+00:00', '2026-08-18T19:31:26.272+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
