INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('2610508506051844', 'atualizacao_lista_contatos', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Olá, {{1}}! \\nBoa tarde.\\nEstamos atualizando a nossa lista de contatos da Radio da Sua Loja.\\nVocê deseja continuar recebendo as nossas mensagens e novidades sobre marketing sensorial?\\nPor favor, selecione uma das opções abaixo para atualizar o seu cadastro.", "type": "BODY", "example": {"body_text": [["Exemplo"]]}}, {"type": "BUTTONS", "buttons": [{"text": "Sim, quero continuar", "type": "QUICK_REPLY"}, {"text": "Não, pode remover", "type": "QUICK_REPLY"}]}]', '2026-08-03T19:48:59.989342+00:00', '2026-08-18T19:31:28.386+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('3462867877202433', 'teste', 'MARKETING', 'pt_BR', 'APPROVED', '[{"type": "HEADER", "format": "IMAGE", "example": {"header_handle": ["https://aossudsganqiapcoqthe.supabase.co/storage/v1/object/public/crm-media/templates/teste_header_1787577684888.jpg"]}}, {"text": "Vim te avisar que estamos com uma promoção imperdível! GOSTARIA DE SABER MAIS?", "type": "BODY"}, {"type": "BUTTONS", "buttons": [{"text": "Sim", "type": "QUICK_REPLY"}, {"text": "não", "type": "QUICK_REPLY"}]}]', '2026-07-14T16:56:45.772188+00:00', '2026-08-24T13:21:26.505+00:00', NULL, 'false', NULL, 'false', '23753033-cdf5-4d2d-9d50-9f4807c45260') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('4465380637046390', 'radio_venceu', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Olá {{1}}\\nInformamos que a assinatura de sua rádio venceu hoje.", "type": "BODY", "example": {"body_text": [["Exemplo"]]}}]', '2026-08-18T19:22:18.795383+00:00', '2026-08-18T19:31:24.573+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('4516639541991424', 'abordagem_inicial_academias', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "\\"Olá, tudo bem? \\nFalo com o responsável pela gestão da {{1}}?\\n\\nMe chamo Frank Eler, sou especialista em marketing sensorial na Radio da Sua Loja. \\n\\nNotei a estrutura de vocês e liberei um acesso de 7 dias de teste gratuito da nossa plataforma de Rádio Interna para Academias.\\n\\nCom o nosso sistema, você consegue aumentar o foco dos alunos com playlists por batidas (BPM) ideais para treino, divulgar avisos automaticamente e eliminar o risco de multas do ECAD por usar apps de uso pessoal (como Spotify).\\n\\nA instalação é 100% online e leva menos de 5 minutos. \\n\\nPosso liberar o acesso gratuito para vocês testarem essa semana?\\"", "type": "BODY", "example": {"body_text": [["Exemplo"]]}}, {"type": "BUTTONS", "buttons": [{"text": "Quero testar grátis", "type": "QUICK_REPLY"}, {"text": "Agora não, obrigado", "type": "QUICK_REPLY"}]}]', '2026-08-03T12:59:51.453856+00:00', '2026-08-18T19:31:28.806+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('972945895766323', 'oi_', 'MARKETING', 'pt_BR', 'APPROVED', '[{"text": "Oi", "type": "BODY"}]', '2026-08-01T18:58:47.295232+00:00', '2026-08-24T13:21:24.214+00:00', NULL, 'false', NULL, 'false', '23753033-cdf5-4d2d-9d50-9f4807c45260') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('984992360795308', 'teste0', 'MARKETING', 'pt_BR', 'APPROVED', '[{"text": "teste", "type": "BODY"}]', '2026-06-10T17:32:24.546616+00:00', '2026-06-16T17:27:00.667+00:00', NULL, 'false', NULL, 'false', '318e09c0-9a3b-4275-b9db-dde3de21efd4') ON CONFLICT DO NOTHING;
INSERT INTO public.crm_templates (id, name, category, language, status, components, created_at, updated_at, knowledge_description, is_pix, pix_code, is_carousel, user_id) VALUES ('994038187011971', 'abordagem_neutra', 'MARKETING', 'pt_BR', 'APPROVED', E'[{"text": "Como vai?\\n\\nAqui é Frank Eler, da Spots Brasil\\n\\nTrabalhamos com soluções que geram resultados para lojas e supermercados:\\n\\n✅ Propaganda Para Porta de Loja com 5 horas de musica com fala do locutor de musica em música.\\n\\n✅ Criamos Radio da Sua Loja com todas as gravações mensais inclusas.\\n\\nSe tiver interesse é só chamar.\\n\\nTenha uma excelente semana!", "type": "BODY"}]', '2026-08-17T15:20:09.445245+00:00', '2026-08-18T19:31:25.856+00:00', NULL, 'false', NULL, 'false', 'f0f39ec7-8c7a-4e7e-97a6-4844654c7611') ON CONFLICT DO NOTHING;

